import React, { useState, useEffect } from 'react';
import { getLatestMovies, getRecommendedMovies } from '../api/tmdb';

function MovieSlider() {
  const [latestMovies, setLatestMovies] = useState([]);
  const [recommendedMovies, setRecommendedMovies] = useState([]);

  useEffect(() => {
    const fetchMovies = async () => {
      const latest = await getLatestMovies();
      const recommended = await getRecommendedMovies();
      setLatestMovies(latest.slice(0, 5));
      setRecommendedMovies(recommended.slice(0, 5));
    };
    fetchMovies();
  }, []);

  return (
    <div className="slider-wrapper">
      <section className="hero-slider-section">
        <h2 className="section-title">THE LATEST MOVIES</h2>
        <div className="poster-slider">
          {latestMovies.map((movie) => (
            <div key={movie.id} className="magazine-card">
              <img 
                src={`https://image.tmdb.org/t/p/w500${movie.poster_path}`} 
                alt={movie.title} 
              />
              <p className="card-title">{movie.title}</p>
            </div>
          ))}
        </div>
      </section>

      <section className="recommended-slider-section">
        <h2 className="section-title">CURATED FOR YOU : 맞춤 추천 픽</h2>
        <div className="poster-slider">
          {recommendedMovies.map((movie) => (
            <div key={movie.id} className="magazine-card">
              <img 
                src={`https://image.tmdb.org/t/p/w500${movie.poster_path}`} 
                alt={movie.title} 
              />
              <p className="card-title">{movie.title}</p>
            </div>
          ))}
        </div>
      </section>
    </div>
  );
}

export default MovieSlider;
